mapper.update:
update dish
name = #{name}, category_id = #{categoryId}, merchant_id = #{merchantId}, price = #{price}, image = #{image}, description = #{description}, status = #{status}, update_time = #{updateTime}, update_user = #{updateUser},
where id = #{id}

mapper.select:
select d.*,c.name as categoryName from dish d left join category c on d.category_id = c.id

     and d.name like concat('%',#{name},'%') 
     and d.category_id = #{categoryId} 
     and d.status = #{status} 



order by create_time desc
